INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (216, 1, '-maxdepth', '`a` 폴더 안에 `top.txt`, 폴더 `b`, 그리고 `b` 안에 `mid.txt` 가 있습니다. `find a -maxdepth 1` 은 무엇을 출력할까요?', '깊이를 한 단계로 제한해요.', NULL, NULL, '[]', 'choice', '["`a/b/mid.txt` 까지 모든 하위 항목을 깊이 제한 없이 폴더별로 묶어서 모두 출력한다", "`a` 폴더 자체는 빼고 그 바로 아래에 있는 항목만 이름순으로 골라서 출력한다", "`a`, `a/b`, `a/top.txt` 처럼 `a` 와 그 바로 아래 항목만 출력한다", "`a` 폴더의 이름 하나만 출력하고 안은 들여다보지 않는다"]', 2, '`-maxdepth 0` 이면 `a` 자신만, `-mindepth 2 -maxdepth 2` 이면 정확히 두 단계 아래 항목만 나옵니다.', NULL, NULL, NULL, NULL),
  (216, 2, '-o 와 -print', '`a` 아래에 `.txt` 파일과 `.log` 파일이 있습니다. `find a -name ''*.txt'' -o -name ''*.log'' -print` 는 무엇을 출력할까요?', '-print 가 어디에 붙는지 보세요.', NULL, NULL, '[]', 'choice', '["`.txt` 와 `.log` 파일이 모두 출력되고 `.log` 파일은 두 번 출력된다", "`.log` 파일만 출력된다. `-print` 가 `-o` 오른쪽에만 걸린다", "`-print` 가 두 번 해석되어 구문 오류가 나고 아무것도 출력되지 않는다", "`.txt` 파일만 출력된다. 왼쪽 조건이 먼저 평가된다"]', 1, '`-print` 를 빼면 `.txt` 와 `.log` 가 모두 출력됩니다.', NULL, NULL, NULL, NULL),
  (216, 3, '! 조건', '`find a -type f ! -name ''*.txt''` 는 무엇을 출력할까요?', '! 는 뒤의 조건을 뒤집어요.', NULL, NULL, '[]', 'choice', '["이름이 `.txt` 로 끝나지 않는 일반 파일만 출력한다", "이름이 `.txt` 로 끝나는 일반 파일만 모아서 출력한다", "`.txt` 가 아닌 파일과 모든 폴더까지 함께 모두 출력한다", "`!` 때문에 오류가 나서 아무것도 출력하지 않는다"]', 0, '`-not` 도 같은 뜻입니다.', NULL, NULL, NULL, NULL),
  (216, 4, '-empty', '`find . -empty` 는 무엇을 출력할까요?', '파일과 폴더 모두에 쓰여요.', NULL, NULL, '[]', 'choice', '["크기가 0인 파일만 출력하고 비어 있는 폴더는 제외한다", "비어 있는 폴더만 출력하고 크기가 0인 파일은 제외한다", "이름이 없는 파일과 폴더를 찾아서 출력한다", "내용이 없는 파일과 비어 있는 폴더를 모두 출력한다"]', 3, '파일만 보려면 `-type f` 를 함께 씁니다.', NULL, NULL, NULL, NULL),
  (216, 5, '-newer', '`find . -newer ref` 는 무엇을 출력할까요?', '기준 파일과 수정 시각을 비교해요.', NULL, NULL, '[]', 'choice', '["`ref` 보다 수정 시각이 이른 항목을 모두 출력하고 `ref` 자신도 함께 출력한다", "`ref` 와 같은 내용을 가진 파일만 내용을 비교해서 출력한다", "`ref` 보다 수정 시각이 나중인 항목을 출력한다. `ref` 자신은 나오지 않는다", "`ref` 를 만든 사용자와 같은 소유자의 항목을 출력한다"]', 2, '기준 파일은 `touch -d` 로 시각을 정해 두고 쓸 수 있습니다.', NULL, NULL, NULL, NULL),
  (216, 6, '-size 1k 는 올림', '`find . -size 1k` 는 1025바이트인 파일과 1바이트인 파일 중 어느 쪽에 일치할까요?', 'k 단위로 올려서 비교해요.', NULL, NULL, '[]', 'choice', '["1025바이트는 일치하고 1바이트는 일치하지 않는다. 크기를 가장 가까운 `k` 로 반올림해서 비교한다", "1025바이트는 일치하지 않고 1바이트는 일치한다. 크기를 `k` 단위로 올려서 비교한다", "둘 다 일치한다. `k` 는 1000바이트 이하를 모두 뜻하므로 크기와 상관없다", "둘 다 일치하지 않는다. 정확히 1024바이트인 파일만 일치한다"]', 1, '1024바이트인 파일은 일치하고 1025바이트는 `2k` 로 계산됩니다.', NULL, NULL, NULL, NULL),
  (216, 7, '-size -1k', '`find . -size -1k` 는 어떤 파일에 일치할까요?', '올림하면 1바이트도 1k 가 돼요.', NULL, NULL, '[]', 'choice', '["크기가 0바이트인 빈 파일만 일치한다. 1바이트도 `1k` 로 계산된다", "1024바이트보다 작은 모든 파일이 빠짐없이 일치하고 0바이트도 포함된다", "1바이트 파일은 일치하고 0바이트 파일은 일치하지 않는다. 올림하지 않는다", "크기가 1킬로바이트 미만인 폴더만 골라서 일치한다"]', 0, '`-size +1k` 는 1k 로 올려도 1을 넘는 파일, 즉 1025바이트 이상에 일치합니다.', NULL, NULL, NULL, NULL),
  (216, 8, '-mtime +2', '3일 전에 수정한 파일은 `-mtime +2`, `-mtime -2`, `-mtime 1` 중 어디에 일치할까요?', '+ 는 넘게, - 는 안쪽을 뜻해요.', NULL, NULL, '[]', 'choice', '["`-mtime -2` 에만 일치한다. 2일 안에 수정된 파일을 뜻한다", "`-mtime 1` 에만 일치한다. 정확히 하루 전 파일을 뜻한다", "셋 모두 일치한다. 수정 시각은 날짜만 비교해서 같다", "`-mtime +2` 에만 일치한다. 2일을 넘게 지난 파일을 뜻한다"]', 3, '하루 전에 수정한 파일은 `-mtime -2` 와 `-mtime 1` 에 일치합니다.', NULL, NULL, NULL, NULL),
  (216, 9, '-exec ; 와 +', '`.txt` 파일이 3개일 때 `-exec 명령 {} ;` 와 `-exec 명령 {} +` 는 명령을 각각 몇 번 실행할까요?', '+ 는 모아서 넘겨요.', NULL, NULL, '[]', 'choice', '["`;` 는 1번, `+` 는 3번 실행한다", "둘 다 3번 실행하고 `+` 는 출력만 한 줄로 모은다", "`;` 는 3번, `+` 는 1번 실행한다", "둘 다 1번 실행하고 `;` 는 마지막 파일만 처리한다"]', 2, '`;` 는 셸에서 `\\;` 처럼 막아 써야 합니다. `+` 는 파일 이름을 모아서 한 번에 넘깁니다.', NULL, NULL, NULL, NULL),
  (216, 10, '-print0 와 xargs -0', '`find . -type f | xargs ls` 는 `my file.txt` 에서 어떤 문제가 생기고, `-print0` 와 `xargs -0` 는 무엇을 바꿀까요?', '공백이 구분자로 쓰여요.', NULL, NULL, '[]', 'choice', '["이름이 소문자로 바뀌어 전달되어 파일을 찾지 못하고, `-0` 이 원래 이름으로 되돌린다", "공백에서 이름이 `my`, `file.txt` 로 쪼개지고, 널 문자로 구분하면 한 이름으로 처리된다", "공백이 든 이름은 조용히 건너뛰고, `-0` 이 건너뛴 이름을 다시 처리하게 해 준다", "문제가 없고 `-print0` 은 출력을 한 줄로 합쳐 주기만 할 뿐 결과는 같다"]', 1, '파일 이름에 공백이 있을 수 있으면 항상 `-print0 | xargs -0` 짝으로 씁니다.', NULL, NULL, NULL, NULL),
  (216, 11, '-prune', '`a` 아래에 폴더 `b` 가 있습니다. `find a -path a/b -prune -o -type f -print` 는 무엇을 할까요?', 'prune 은 가지치기예요.', NULL, NULL, '[]', 'choice', '["`a/b` 안은 들어가지 않고 나머지 일반 파일만 출력한다", "`a/b` 안의 일반 파일만 골라서 출력하고 나머지는 건너뛴다", "`a/b` 폴더를 삭제한 뒤 나머지 일반 파일을 출력한다", "`a/b` 의 파일을 마지막에 따로 모아서 출력한다"]', 0, '`-prune` 은 보통 `-o` 와 함께 쓰고 뒤에 `-print` 를 둡니다.', NULL, NULL, NULL, NULL),
  (216, 12, '-name 은 이름만', '`find a -name ''a/top.txt''` 는 무엇을 출력할까요?', 'name 은 경로가 아니라 이름 부분만 봐요.', NULL, NULL, '[]', 'choice', '["`a/top.txt` 를 출력한다. `-name` 은 이름이 아니라 경로 전체를 처음부터 끝까지 비교한다", "오류가 나서 종료 코드가 `1` 이 되고 아무것도 출력하지 않는다", "`a` 아래의 모든 파일을 이름에 상관없이 출력한다", "아무것도 출력하지 않는다. `-name` 은 경로가 아니라 이름 부분만 비교한다"]', 3, '경로로 고르려면 `-path ''a/top.txt''` 를 씁니다.', NULL, NULL, NULL, NULL),
  (216, 13, '-iname', '`UP.TXT` 파일이 있을 때 `find . -iname ''*.txt''` 는 이 파일을 찾을까요?', 'i 는 ignore case 예요.', NULL, NULL, '[]', 'choice', '["찾지 못한다. `-name` 과 같아서 대소문자를 구분해서 비교한다", "찾지 못한다. `.TXT` 는 `-iname` 이 아니라 `-name` 으로만 찾는다", "찾는다. `-iname` 은 대소문자를 구분하지 않고 이름을 비교한다", "찾지만 `-name` 과 달리 폴더까지 함께 출력해 준다"]', 2, '`-name ''*.txt''` 는 `UP.TXT` 를 찾지 못합니다.', NULL, NULL, NULL, NULL),
  (216, 14, 'find 의 종료 코드', '`find a -name nomatch` 처럼 일치하는 항목이 없을 때와 `find nosuchdir` 처럼 없는 경로를 줄 때 종료 코드는 각각 얼마일까요?', 'grep 과 달라요.', NULL, NULL, '[]', 'choice', '["일치하는 항목이 없으면 `1` 이고, 있으면 `0` 이며, 경로 오류는 `2` 이다", "일치하는 항목이 없어도 `0` 이고, 없는 경로를 주면 `1` 이다", "일치하는 항목이 없으면 `127` 이고, 경로 오류가 나면 `2` 로 끝난다", "항상 `0` 이고 오류가 나도 메시지만 출력한다"]', 1, '`grep` 은 일치가 없으면 `1` 이지만 `find` 는 아닙니다.', NULL, NULL, NULL, NULL),
  (216, 15, '깊이 제한하기', '`find` 에서 **내려갈 폴더 깊이의 최대를 정하는** 조건을 채우세요.', '"최대 깊이"를 영어로 이어 써요.', NULL, NULL, '[]', 'fill', '["-depth", "-level", "-limit", "-maxdepth"]', NULL, '`-mindepth` 는 최소 깊이입니다.', '[3]', 'find a {0} 1', NULL, NULL),
  (216, 16, '대소문자 무시', '`find` 에서 **대소문자를 구분하지 않고 이름을 비교하는** 조건을 채우세요.', '"ignore"의 첫 글자를 붙여요.', NULL, NULL, '[]', 'fill', '["iname", "name", "nocase", "ignore"]', NULL, '그냥 `-name` 은 대소문자를 구분합니다.', '[0]', 'find . -{0} ''*.txt''', NULL, NULL),
  (216, 17, '빈 파일과 폴더', '`find` 에서 **비어 있는 파일과 폴더를 찾는** 조건을 채우세요.', '"비어 있는"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["blank", "empty", "zero", "void"]', NULL, '파일만 보려면 `-type f` 를 함께 씁니다.', '[1]', 'find . -{0}', NULL, NULL),
  (216, 18, '더 나중에 수정', '`find` 에서 **기준 파일보다 수정 시각이 나중인 항목을 찾는** 조건을 채우세요.', '"더 새로운"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["after", "later", "newer", "since"]', NULL, '기준 파일 자신은 나오지 않습니다.', '[2]', 'find . -{0} ref', NULL, NULL),
  (216, 19, '일반 파일만', '`find` 에서 **일반 파일만 고르는** `-type` 값을 채우세요.', '"file"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["d", "l", "s", "f"]', NULL, '폴더는 `d`, 심볼릭 링크는 `l` 입니다.', '[3]', 'find . -type {0}', NULL, NULL),
  (216, 20, '크기로 고르기', '`find` 에서 **파일 크기로 거르는** 조건을 채우세요.', '"크기"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["size", "length", "bytes", "big"]', NULL, '`k` 단위로 올려서 비교합니다.', '[0]', 'find . -{0} +1k', NULL, NULL),
  (216, 21, '수정한 지 며칠', '`find` 에서 **수정한 지 며칠이 지났는지로 거르는** 조건을 채우세요.', '"수정 시각"을 뜻하는 m 으로 시작해요.', NULL, NULL, '[]', 'fill', '["atime", "mtime", "ctime", "days"]', NULL, '`+2` 는 2일을 넘게 지난 파일입니다.', '[1]', 'find . -{0} +2', NULL, NULL),
  (216, 22, '찾은 항목마다 실행', '`find` 가 **찾은 항목으로 명령을 실행하게 하는** 동작을 채우세요.', '"실행하다"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["run", "do", "exec", "call"]', NULL, '`;` 로 끝내면 파일마다 한 번씩 실행합니다.', '[2]', 'find . -name ''*.txt'' -{0} echo {} +', NULL, NULL),
  (216, 23, '널 문자로 구분해 출력', '`find` 가 **이름을 널 문자로 구분해 출력하게 하는** 동작을 채우세요.', '"print"에 숫자 0 을 붙여요.', NULL, NULL, '[]', 'fill', '["null", "zero", "nul", "print0"]', NULL, '공백이 든 이름도 안전하게 넘길 수 있습니다.', '[3]', 'find . -{0} | xargs -0 ls', NULL, NULL),
  (216, 24, '찾은 파일 바로 지우기', '`find` 가 **찾은 항목을 바로 지우게 하는** 동작을 채우세요.', '"삭제하다"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["delete", "remove", "rm", "unlink"]', NULL, '먼저 `-delete` 를 빼고 무엇이 나오는지 확인합니다.', '[0]', 'find del -type f -{0}', NULL, NULL),
  (216, 25, '폴더 건너뛰기', '`find` 에서 **일치한 폴더 안으로는 들어가지 않게 하는** 동작을 채우세요.', '"가지치기"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["skip", "prune", "ignore", "exclude"]', NULL, '뒤에 `-print` 를 두어야 나머지가 출력됩니다.', '[1]', 'find a -path a/b -{0} -o -type f -print', NULL, NULL),
  (216, 26, '일반 파일 좁혀 찾기', '`find` 조건을 하나씩 더해 찾는 범위를 좁히는 순서입니다. 순서에 맞게 놓아 보세요.', '전부 → 파일 → txt → 빈 파일 제외 순서예요.', NULL, NULL, '[]', 'order', '["`find a -type f -name ''*.txt'' -size +0` 로 빈 파일이 빠지는지 확인한다", "`find a -type f -name ''*.txt''` 로 `.txt` 파일만 남는지 확인한다", "`find a` 로 `a` 아래 모든 항목을 본다", "`find a -type f` 로 일반 파일만 남는지 확인한다"]', NULL, '`-size +0` 은 크기가 0보다 큰 파일입니다.', '[2, 3, 1, 0]', NULL, NULL, NULL),
  (216, 27, '공백 이름 안전하게 처리', '이름에 공백이 든 파일을 안전하게 처리하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 실패 확인 → 고치기 → 지우기 순서예요.', NULL, NULL, '[]', 'order', '["`find w -type f -print0 | xargs -0 ls` 가 이름을 그대로 출력하는지 확인한다", "`find w -type f -print0 | xargs -0 rm` 으로 지우고 `find w -type f` 가 비었는지 확인한다", "`find w -type f | xargs ls` 가 이름이 쪼개져 오류를 내는지 확인한다", "`w/my file.txt` 처럼 이름에 공백이 든 파일을 만든다"]', NULL, '공백 이름은 항상 `-print0 | xargs -0` 짝으로 씁니다.', '[3, 2, 0, 1]', NULL, NULL, NULL),
  (216, 28, '명령 한 번에 모아 실행', '`-exec` 의 두 가지 끝맺음을 비교하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → ; → + → 목록 순서예요.', NULL, NULL, '[]', 'order', '["`-exec sh -c ''echo run'' _ {} +` 로 바꾸면 `run` 이 1줄만 나오는지 확인한다", "`c/1.txt`, `c/2.txt`, `c/3.txt` 를 만든다", "`find c -name ''*.txt'' -exec ls {} +` 로 세 파일이 한 번에 나오는지 확인한다", "`find c -name ''*.txt'' -exec sh -c ''echo run'' _ {} ;` 가 `run` 을 3줄 출력하는지 확인한다"]', NULL, '`;` 는 셸에서 `\\;` 처럼 막아서 씁니다.', '[1, 3, 0, 2]', NULL, NULL, NULL),
  (216, 29, '시간으로 고르기', '수정 시각으로 파일을 고르는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 오래된 것 → 새 것 → 기준 비교 순서예요.', NULL, NULL, '[]', 'order', '["`find d -name ''*.txt'' -mtime +2` 로 `old.txt` 만 나오는지 확인한다", "`find d -name ''*.txt'' -newer d/old.txt` 로 `old.txt` 보다 나중인 `new.txt` 만 나오는지 확인한다", "`touch -d ''3 days ago'' d/old.txt` 와 `touch d/new.txt` 로 두 파일을 만든다", "`find d -name ''*.txt'' -mtime -2` 로 `new.txt` 만 나오는지 확인한다"]', NULL, '`-newer` 는 기준 파일 자신을 출력하지 않습니다.', '[2, 0, 3, 1]', NULL, NULL, NULL);
